const e = $input.first().json;
const ex = e.execution || {};
const wf = e.workflow || {};
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const html = '<h2>⚠️ Falló un workflow de AgroTech</h2>' +
  '<p><b>Workflow:</b> ' + esc(wf.name) + '</p>' +
  '<p><b>Nodo:</b> ' + esc(ex.lastNodeExecuted) + '</p>' +
  '<p><b>Error:</b> ' + esc(ex.error && ex.error.message) + '</p>' +
  '<p><b>Ejecución:</b> ' + esc(ex.id) + (ex.url ? ' — <a href="' + esc(ex.url) + '">abrir en n8n</a>' : '') + '</p>' +
  '<p>Mientras esto no se arregle, algunos avisos (email/WhatsApp) pueden no estar llegando.</p>';
return [{ json: { asunto: '⚠️ AgroTech: falló ' + (wf.name || 'un workflow'), html } }];
